public class Main {
    static class MaxFlowSolver {
        static class Edge {
            int from, to;
            long flow, capacity;
            public Edge(int from, int to, long flow, long capacity) {
                this.from = from;
                this.to = to;
                this.flow = flow;
                this.capacity = capacity;
            }
        }

        int s, t;
        List<Edge> edges = new ArrayList<>();
        List<Integer>[] adj = new ArrayList[7100];
        int[] level = new int[7100], current = new int[7100];

        public MaxFlowSolver() {
            for (int i = 0; i < 7100; i++) {
                adj[i] = new ArrayList<>();
            }
        }

        void reset() {
            edges.clear();
            for (int i = 0; i < 7100; i++) {
                adj[i].clear();
            }
        }

        void addEdge(int u, int v, long cap) {
            edges.add(new Edge(u, v, 0, cap));
            edges.add(new Edge(v, u, 0, 0));
            adj[u].add(edges.size() - 2);
            adj[v].add(edges.size() - 1);
        }

        boolean buildLevelGraph() {
            Arrays.fill(level, -1);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            level[s] = 0;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int idx : adj[u]) {
                    Edge e = edges.get(idx);
                    if (e.capacity > e.flow && level[e.to] < 0) {
                        level[e.to] = level[u] + 1;
                        q.offer(e.to);
                    }
                }
            }
            return level[t] >= 0;
        }

        long sendFlow(int u, long flow) {
            if (u == t || flow == 0) return flow;
            long totalSent = 0;
            for (int i = current[u]; i < adj[u].size(); i++) {
                int idx = adj[u].get(i);
                Edge e = edges.get(idx);
                if (level[e.to] == level[u] + 1 && e.capacity > e.flow) {
                    long pushed = sendFlow(e.to, Math.min(flow, e.capacity - e.flow));
                    if (pushed > 0) {
                        e.flow += pushed;
                        edges.get(idx ^ 1).flow -= pushed;
                        totalSent += pushed;
                        flow -= pushed;
                        if (flow == 0) break;
                    }
                }
                current[u]++;
            }
            return totalSent;
        }

        long maxFlow() {
            long totalFlow = 0;
            while (buildLevelGraph()) {
                Arrays.fill(current, 0);
                totalFlow += sendFlow(s, Long.MAX_VALUE);
            }
            return totalFlow;
        }
    }

    static char[][] mazeX = new char[14][14];
    static char[][] mazeY = new char[14][14];
    static boolean[][] visitedCells = new boolean[14][14];
    static int[][] distMap = new int[14][14];
    static int n;
    static int[] targetIdx = new int[103];

    static void performBFS(int x, int y) {
        for (int i = 0; i < 14; i++)
            Arrays.fill(distMap[i], 111);
        Queue<int[]> q = new LinkedList<>();
        distMap[x][y] = 0;
        q.offer(new int[]{x, y, 0});
        int[] dx = {1, 0, 0, -1};
