                            if (distMap[j][k] >= i && distMap[tx][ty] >= i) {
                                solver.addEdge(getIdx(i - 1, tx, ty), getIdx(i, j, k), Long.MAX_VALUE);
                            }
                        }
                    }
                    solver.addEdge(getIdx(i, j, k), targetIdx[getIdx(0, j, k)], Long.MAX_VALUE);
                }
            }
        }

        System.out.println(solver.maxFlow());
    }
